onent-export="default" renderer-url="/_astro/client.8CyCEayk.js" props="{&quot;featuredImage&quot;:[0,&quot;https://media.fittour.vn/uploads/du-lich-alaska-usa-phan-7-ca-voi-alaska-nhung-ga-khong-lo-cua-bien-phuong-bac.webp&quot;],&quot;config&quot;:[0,{&quot;title&quot;:[0,&quot;Alaska: Mùa Ngắm Cá Voi – Trải Nghiệm Không Thể Bỏ Lỡ Ở Vùng Cực Bắc (Phần 7)&quot;],&quot;seriesTitle&quot;:[0,&quot;ALASKA&quot;],&quot;heroSubtitle&quot;:[0,&quot;Mùa Ngắm Cá Voi – Trải Nghiệm Không Thể Bỏ Lỡ Ở Vùng Cực Bắc&quot;],&quot;heroChapter&quot;:[0,&quot;PHẦN VII • VŨ ĐIỆU CỦA ĐẠI DƯƠNG&quot;],&quot;heroQuote&quot;:[0,&quot;\&quot;Bởi khi một con cá voi lưng gù từ từ nổi lên giữa mặt biển bao la rồi lặn xuống làn nước xanh thẳm, đó không chỉ là một cuộc gặp gỡ với động vật hoang dã. Đó là cơ hội để con người cảm nhận sự kỳ vĩ của thiên nhiên theo cách chân thực nhất.\&quot;&quot;],&quot;heroImage&quot;:[0,&quot;https://media.fittour.vn/uploads/2025/11/tour-alaska-fittour.webp&quot;],&quot;sections&quot;:[1,[[0,{&quot;id&quot;:[0,&quot;whale-intro&quot;],&quot;order&quot;:[0,1],&quot;title&quot;:[0,&quot;GÃ KHỔNG LỒ CỦA ĐẠI DƯƠNG&quot;],&quot;subtitle&quot;:[0,&quot;KHOẢNH KHẮC ĐÁNG NHỚ NHẤT&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Nếu có một trải nghiệm khiến nhiều du khách nhớ mãi sau chuyến đi Alaska, đó thường là khoảnh khắc nhìn thấy cá voi xuất hiện giữa đại dương.&quot;],[0,&quot;Giữa vùng biển lạnh giá của phương Bắc, mặt nước bỗng chuyển động, rồi một thân hình khổng lồ từ từ nổi lên.&quot;],[0,&quot;Tiếng thở vang vọng trên mặt biển, chiếc đuôi lớn hất lên trước khi lặn sâu xuống là những hình ảnh khiến nhiều người không thể quên.&quot;],[0,&quot;Alaska từ lâu được xem là một trong những điểm đến hàng đầu thế giới để ngắm cá voi trong môi trường tự nhiên.&quot;],[0,&quot;Mỗi mùa hè, hàng nghìn cá thể cá voi di cư về đây để kiếm ăn, tạo nên một trong những hiện tượng thiên nhiên ấn tượng nhất của vùng đất này.&quot;]]],&quot;highlightText&quot;:[0,&quot;Tiếng thở vang vọng trên mặt biển, chiếc đuôi lớn hất lên trước khi lặn sâu xuống là những hình ảnh khiến nhiều người không thể quên.&quot;]}],[0,{&quot;id&quot;:[0,&quot;di-cu&quot;],&quot;order&quot;:[0,2],&quot;title&quot;:[0,&quot;Hành Trình Di Cư Hàng Nghìn Kilomet&quot;],&quot;subtitle&quot;:[0,&quot;CHIẾN LƯỢC SINH TỒN VĨ ĐẠI&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Loài cá voi được bắt gặp nhiều nhất tại Alaska là cá voi lưng gù.&quot;],[0,&quot;Một cá thể trưởng thành có thể dài từ 12 đến 16 mét và nặng hàng chục tấn. Tuy nhiên, phần lớn thời gian trong năm chúng không sống ở Alaska.&quot;],[0,&quot;Vào mùa đông, cá voi lưng gù di chuyển xuống các vùng biển ấm hơn như Hawaii, Mexico hoặc Trung Mỹ để sinh sản. Khi mùa xuân đến, chúng bắt đầu hành trình trở lại vùng biển Alaska để tìm nguồn thức ăn dồi dào.&quot;],[0,&quot;Quãng đường di cư có thể vượt quá 5.000 kilomet, thuộc nhóm những hành trình dài nhất của động vật có vú trên hành tinh.&quot;],[0,&quot;Điều thú vị là nhiều cá thể vẫn quay lại đúng khu vực kiếm ăn quen thuộc qua từng năm. Đây là hiện tượng mà các nhà khoa học vẫn đang tiếp tục nghiên cứu để hiểu rõ hơn về khả năng định hướng đáng kinh ngạc của chúng.&quot;]]],&quot;highlightText&quot;:[0,&quot;Quãng đường di cư có thể vượt quá 5.000 kilomet, thuộc nhóm những hành trình dài nhất của động vật có vú trên hành tinh.&quot;]}],[0,{&quot;id&quot;:[0,&quot;vi-sao-tap-trung&quot;],&quot;order&quot;:[0,3],&quot;title&quot;:[0,&quot;Vì Sao Cá Voi Tập Trung Nhiều Ở Alaska?&quot;],&quot;subtitle&quot;:[0,&quot;KHO THỨC ĂN KHỔNG LỒ&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Mùa hè Alaska mang đến điều kiện lý tưởng cho các loài sinh vật biển phát triển.&quot;],[0,&quot;Ánh sáng kéo dài gần như suốt ngày giúp sinh vật phù du sinh sôi mạnh mẽ. Đây là mắt xích đầu tiên trong chuỗi thức ăn của đại dương, tạo nguồn dinh dưỡng dồi dào cho cá nhỏ, nhuyễn thể và nhiều loài sinh vật khác.&quot;],[0,&quot;Đối với cá voi, vùng biển Alaska giống như một \&quot;kho thức ăn\&quot; khổng lồ.&quot;],[0,&quot;Một con cá voi lưng gù có thể tiêu thụ lượng thức ăn rất lớn mỗi ngày để tích lũy năng lượng cho hành trình quay về phương Nam khi mùa hè kết thúc.&quot;],[0,&quot;Nhờ nguồn thức ăn phong phú này, du khách thường có cơ hội quan sát nhiều hoạt động tự nhiên thú vị của cá voi, đặc biệt là kỹ thuật săn mồi nổi tiếng mang tên bubble-net feeding.&quot;],[0,&quot;Trong kỹ thuật này, một nhóm cá voi phối hợp tạo vòng bong bóng dưới nước để gom đàn cá lại trước khi đồng loạt lao lên kiếm ăn.&quot;],[0,&quot;Đây được xem là một trong những hành vi săn mồi độc đáo nhất trong thế giới động vật biển.&quot;]]],&quot;highlightText&quot;:[0,&quot;Trong kỹ thuật này, một nhóm cá voi phối hợp tạo vòng bong bóng dưới nước để gom đàn cá lại trước khi đồng loạt lao lên kiếm ăn.&quot;]}],[0,{&quot;id&quot;:[0,&quot;dia-diem-ngam&quot;],&quot;order&quot;:[0,4],&quot;title&quot;:[0,&quot;Những Địa Điểm Ngắm Cá Voi Nổi Tiếng Ở Alaska&quot;],&quot;subtitle&quot;:[0,&quot;CHUYẾN ĐI VÀO LÒNG BIỂN&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Alaska có nhiều khu vực nổi tiếng với tỷ lệ bắt gặp cá voi rất cao trong mùa hè.&quot;],[0,&quot;Một số điểm đến được nhiều du khách lựa chọn gồm: Juneau, Seward, Kenai Fjords National Park, và Glacier Bay National Park.&quot;],[0,&quot;Từ các cảng biển địa phương, du khách có thể tham gia các tour ngắm cá voi kéo dài từ vài giờ đến cả ngày.&quot;],[0,&quot;Ngoài cá voi, nhiều chuyến đi còn kết hợp quan sát sư tử biển, rái cá biển, hải cẩu và đại bàng đầu trắng – biểu tượng nổi tiếng của nước Mỹ.&quot;],[0,&quot;Thời gian lý tưởng nhất để ngắm cá voi tại Alaska thường từ tháng 5 đến tháng 9. Trong đó, giai đoạn từ tháng 6 đến tháng 8 là mùa cao điểm với số lượng cá voi xuất hiện nhiều nhất.&quot;]]],&quot;highlightText&quot;:[0,&quot;Ngoài cá voi, nhiều chuyến đi còn kết hợp quan sát sư tử biển, rái cá biển, hải cẩu và đại bàng đầu trắng – biểu tượng nổi tiếng của nước Mỹ.&quot;]}],[0,{&quot;id&quot;:[0,&quot;dieu-dac-biet&quot;],&quot;order&quot;:[0,5],&quot;title&quot;:[0,&quot;Điều Khiến Trải Nghiệm Này Trở Nên Đặc Biệt&quot;],&quot;subtitle&quot;:[0,&quot;VẺ ĐẸP NGUYÊN SƠ&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Nhiều người sau chuyến đi không nhớ chính xác mình đã nhìn thấy bao nhiêu con cá voi.&quot;],[0,&quot;Điều họ nhớ là cảm giác khi tận mắt chứng kiến chúng xuất hiện.&quot;],[0,&quot;Một chiếc đuôi khổng lồ nổi lên giữa mặt biển. Một cú nhảy bất ngờ tạo nên cột nước trắng xóa. Hay tiếng thở mạnh vang lên ngay gần con tàu.&quot;],[0,&quot;Những khoảnh khắc ấy khiến con người cảm nhận rõ hơn sự rộng lớn của đại dương và vẻ đẹp nguyên sơ của thiên nhiên Alaska.&quot;],[0,&quot;Đó là trải nghiệm mà hình ảnh hay video khó có thể truyền tải trọn vẹn.&quot;]]],&quot;highlightText&quot;:[0,&quot;Những khoảnh khắc ấy khiến con người cảm nhận rõ hơn sự rộng lớn của đại dương và vẻ đẹp nguyên sơ của thiên nhiên Alaska.&quot;]}],[0,{&quot;id&quot;:[0,&quot;bao-ton&quot;],&quot;order&quot;:[0,6],&quot;title&quot;:[0,&quot;Cá Voi Và Nỗ Lực Bảo Tồn Thiên Nhiên&quot;],&quot;subtitle&quot;:[0,&quot;SỰ PHỤC HỒI KỲ DIỆU&quot;],&quot;paragraphs&quot;:[1,[[0,&quot;Dù là những sinh vật khổng lồ của đại dương, cá voi từng đối mặt với nguy cơ suy giảm nghiêm trọng do hoạt động săn bắt thương mại trong thế kỷ XIX và XX.&quot;],[0,&quot;Nhờ các chương trình bảo tồn quốc tế, nhiều quần thể cá voi đã dần phục hồi trong những thập kỷ gần đây.&quot;],[0,&quot;Ngày nay, du lịch ngắm cá voi không chỉ mang lại trải nghiệm đáng nhớ cho du khách mà còn góp phần nâng cao nhận thức về việc bảo vệ hệ sinh thái biển.&quot;],[0,&quot;Trong hành trình khám phá Alaska, ngắm cá voi luôn là một trong những hoạt động được mong chờ nhất.&quot;],[0,&quot;Bởi khi một con cá voi lưng gù từ từ nổi lên giữa mặt biển bao la rồi lặn xuống làn nước xanh thẳm, đó không chỉ là một cuộc gặp gỡ với động vật hoang dã.&quot;],[0,&quot;Đó là cơ hội để con người cảm nhận sự kỳ vĩ của thiên nhiên theo cách chân thực nhất.&quot;],[0,&quot;Và chính những khoảnh khắc ấy đã khiến Alaska trở thành điểm đến đặc biệt trong lòng rất nhiều du khách trên thế giới.&quot;]]],&quot;highlightText&quot;:[0,&quot;Đó là cơ hội để con người cảm nhận sự kỳ vĩ của thiên nhiên theo cách chân thực nhất.&quot;]}]]],&quot;partNumber&quot;:[0,7]}],&quot;data-astro-cid-zryocs6i&quot;:[0,true]}" ssr="" client="idle" opts="{&quot;name&quot;:&quot;App&quot;,&quot;value&quot;:true}" await-children=""><div class="min-h-screen bg-[#060B0A] text-[#E5ECE9] selection:bg-emerald-500 selection:text-[#060B0A] transition-all duration-300 antialiased overflow-x-hidden relative font-sans" style="background-image:none"><div class="absolute inset-0 opacity-30 pointer-events-none" style="background-image:url(''data:image/svg+xml,%3Csvg viewBox=&quot;0 0 200 200&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot;%3E%3Cfilter id=&quot;noise&quot;%3E%3CfeTurbulence type=&quot;fractalNoise&quot; baseFrequency=&quot;0.8&quot; numOctaves=&quot;3&quot; stitchTiles=&quot;stitch&quot;/%3E%3C/filter%3E%3Crect width=&quot;100%25&quot; height=&quot;100%25&quot; filter=&quot;url(%23noise)&quot; opacity=&quot;0.015&quot;/%3E%3C/svg%3E'')"></div><section class="relative w-full h-[620px] md:h-[750px] overflow-hidden flex items-center justify-center border-b border-white/5 bg-slate-950"><div class="absolute inset-0 bg-[#09151A]"><img src="https://media.fittour.vn/uploads/du-lich-alaska-usa-phan-7-ca-voi-alaska-nhung-ga-khong-lo-cua-bien-phuong-bac.webp" alt="Alaska Chugach Glacier Mountain Range Backdrop cinematic" fetchpriority="high" class="w-full h-full object-cover object-center filter contrast-[1.05] saturate-[0.8] brightness-[0.45]" referrerpolicy="no-referrer"><div class="absolute inset-0 bg-emerald-950/15 mix-blend-multiply"></div><div class="absolute inset-0 bg-gradient-to-t from-[#060B0A] via-transparent to-transparent pointer-events-none"></div><div class="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-slate-950 to-transparent"></div></div><div class="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40 mix-blend-screen overflow-hidden"><div class="absolute w-[800px] h-[350px] bg-emerald-400/10 rounded-full blur-[120px] -rotate-12 transform -translate-y-24 translate-x-12 animate-pulse"></div><div class="absolute w-[600px] h-[250px] bg-sky-400/10 rounded-full blur-[100px] rotate-12 transform translate-y-24 -translate-x-12"></div></div><div class="max-w-4xl mx-auto px-6 z-20 text-center space-y-8"><div class="space-y-3.5"><span class="font-mono text-[#A8D1DB] text-[12px] md:text-[10px] md:text-[11px] tracking-[0.55em] uppercase font-black block animate-pulse">★ SERIES BLOG TRUYỀN KÝ DÃ NGOẠI ★</span><div class="w-14 h-[1.5px] bg-[#A8D1DB]/50 mx-auto"></div></div><div class="space-y-4"><h1 class="font-prata text-5xl md:text-7xl lg:text-8xl text-white font-normal leading-[0.95] uppercase tracking-tighter drop-shadow-xl select-all">ALASKA</h1><span class="font-serif italic text-2xl md:text-3xl text-amber-300 block font-light tracking-wide">Mùa Ngắm Cá Voi – Trải Nghiệm Không Thể Bỏ Lỡ Ở Vùng Cực Bắc</span><p class="font-sans text-[13px] md:text-[11px] md:text-[12px] tracking-[0.35em] text-cyan-200 uppercase block font-black border-y border-white/5 py-2.5 max-w-lg mx-auto mt-4">PHẦN VII • VŨ ĐIỆU CỦA ĐẠI DƯƠNG</p></div><p class="font-serif text-[15px] md:text-[18px] text-stone-200 font-light leading-relaxed max-w-2xl mx-auto italic select-all mt-8 mb-4">"Bởi khi một con cá voi lưng gù từ từ nổi lên giữa mặt biển bao la rồi lặn xuống làn nước xanh thẳm, đó không chỉ là một cuộc gặp gỡ với động vật hoang dã. Đó là cơ hội để con người cảm nhận sự kỳ vĩ của thiên nhiên theo cách chân thực nhất."</p><div class="pt-8 text-stone-400 space-y-1 select-none animate-bounce"><span class="font-mono text-[10px] md:text-[8px] uppercase tracking-widest block">Kéo xuống để bắt đầu đọc sách</span><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-corner-down-right w-4 h-4 mx-auto text-amber-305 rotate-90" aria-hidden="true"><path d="m15 10 5 5-5 5"></path><path d="M4 4v7a4 4 0 0 0 4 4h12"></path></svg></div></div></section><section class="max-w-4xl mx-auto px-6 pt-12 pb-6 flex flex-col items-center justify-center space-y-4"><span class="font-mono text-[#A8D1DB] text-[12px] md:text-[10px] tracking-[0.45em] uppercase font-black block">★ THỂ HIỆN BÀI VIẾT (PRESENTATION LAYER) ★</span><div class="flex bg-slate-950/90 border border-white/10 p-1 rounded-2xl w-full max-w-md shadow-2xl relative z-40"><button class="flex-1 py-2.5 px-3 rounded-xl font-sans text-sm md:text-xs font-bold uppercase tracking-wider transition-all duration-300 flex items-center justify-center gap-2 cursor-pointer text-stone-400 hover:text-white"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-book-open w-3.5 h-3.5" aria-hidden="true"><path d="M12 7v14"></path><path d="M3 18a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1h-6a3 3 0 0 0-3 3 3 3 0 0 0-3-3z"></path></svg><span>Tạp Chí Địa Lý</span></button><button class="flex-1 py-2.5 px-3 rounded-xl font-sans text-sm md:text-xs font-bold uppercase tracking-wider transition-all duration-300 flex items-center justify-center gap-2 cursor-pointer bg-[#915422] text-amber-100 shadow-md border border-amber-400/20"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-compass w-3.5 h-3.5 animate-spin-slow" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z"></path></svg><span>Sổ Tay Viễn Chinh</span></button></div><p class="font-serif italic text-sm md:text-xs text-stone-400 text-center max-w-lg leading-relaxed">Đậm đặc phong vị Alaska: Trang sách gáy xoắn mộc bọc sương đọng, tọa độ thời tiết thực địa &amp; sớ triện đỏ dán tên lữ hành.</p></section><div class="max-w-4xl mx-auto px-6 py-6"><div class="bg-[#121B1C]/60 border border-white/5 hover:border-white/10 rounded-2xl p-6 md:p-8 relative flex flex-col md:flex-row items-center gap-8 transition-colors duration-500"><div class="shrink-0 relative w-28 h-28 md:w-40 md:h-40 rounded-full overflow-hidden border-[3px] border-[#121B1C] ring-2 ring-amber-500/20 shadow-xl"><img src="https://media.fittour.vn/uploads/max-vu-founder-fit-tour.webp" alt="Max Vũ" class="w-full h-full object-cover"></div><div class="flex-1 text-center md:text-left space-y-4"><div class="flex flex-col md:flex-row md:items-end justify-between gap-4"><div><div class="flex items-center justify-center md:justify-start gap-2 mb-2 flex-wrap"><span class="font-mono text-amber-500 text-[10px] tracking-[0.2em] uppercase font-bold bg-amber-500/10 px-2 py-1 rounded">TÁC GIẢ BÀI VIẾT &amp; TRIP PLANNER</span><span class="font-mono text-stone-400 text-[10px] uppercase font-bold pl-1">CEO FIT TOUR</span><span class="font-mono text-cyan-500/80 text-[10px] italic border-l border-stone-700 pl-2">10 NĂM KINH NGHIỆM</span></div><h2 class="font-serif text-3xl text-white">Max Vũ</h2></div><a href="https://fittour.vn/max-vu" target="_blank" rel="noopener noreferrer" class="inline-block px-6 py-2.5 bg-stone-900 border border-stone-700 hover:border-amber-500 hover:bg-amber-500/10 text-stone-300 hover:text-white font-mono text-[10px] uppercase tracking-widest font-bold rounded-full transition-all duration-300 whitespace-nowrap">XEM HỒ SƠ CHUYÊN GIA</a></div><p class="font-serif text-stone-300 text-[14.5px] leading-relaxed max-w-3xl">Người trực tiếp chắp bút cho series 10 bài viết này và đảm nhiệm vai trò <strong class="text-amber-100 font-medium">Chuyên gia thiết kế hành trình (Trip Planner)</strong> cho tuyến tour Alaska. Bằng kinh nghiệm thực chiến dạn dày, Max Vũ khát vọng đưa du khách vượt ra khỏi ranh giới truyền thống để thực sự chạm đến bản nguyên vĩ đại của miền biên cương Bắc Cực.</p></div></div></div><section class="max-w-4xl mx-auto px-6 py-8 space-y-16 relative"><article id="whale-intro" class="p-6 md:p-10 md:pl-20 md:pr-12 rounded-2xl transition-all duration-300 text-left relative overflow-hidden border-2 bg-[#070F0D] border-emerald-500/25 text-[#E5ECE9] shadow-lg" style="opacity:0;transform:translateY(15px)"><div class="absolute left-3 top-0 bottom-0 hidden md:flex flex-col justify-around py-5 pointer-events-none z-30 select-none"><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div><div class="flex items-center gap-1.5"><div class="w-2 h-2 rounded-full shadow-inner border bg-slate-950/90 border-white/5"></div><div class="w-5.5 h-2.5 rounded-r-full border-t border-r border-b border-slate-500/25 -ml-1"></div></div></div><div class="absolute top-20 right-5 md:right-12 w-28 h-28 rounded-full border border-dashed flex flex-col items-center justify-center p-2 text-center select-none pointer-events-none opacity-40 uppercase font-mono tracking-tighter border-emerald-400/40 text-emerald-300 rotate-6 bg-emerald-950/10"><span class="text-[9px] md:text-[7px] font-black tracking-widest leading-none">FIT TOUR</span><div class="w-16 h-[0.5px] bg-current my-0.5"></div><span class="text-[10.5px] md:text-[8.5px] font-black leading-none">EXPEDITION</span><span class="text-[9px] md:text-[7px] font-bold font-sans text-amber-500 truncate max-w-[80px] my-0.5">Lữ Khách Cực Bắc</span><div class="w-16 h-[0.5px] bg-current my-0.5"></div><span class="text-[9px] md:text-[7px] font-bold tracking-widest leading-none">ARNATIC 26</span></div><div class="border p-4 rounded-xl font-mono text-[12.5px] md:text-[10.5px] mb-6 space-y-1.5 relative z-10 border-white/10 bg-white/[0.015] text-stone-300"><div class="flex items-center justify-between text-sm md:text-xs font-black border-b border-dashed pb-1.5 mb-1 text-amber-500"><span class="flex items-center gap-1"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-compass w-3.5 h-3.5 animate-spin-slow animate-pulse" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z"></path></svg>BẢN THÔNG ĐIỆP ĐỊA TRÌNH</span><span>ENTRY 0<!-- -->1</span></div><div class="grid grid-cols-2 gap-x-4 gap-y-1.5"><div>TỌA ĐỘ: <span class="font-sans font-extrabold text-sky-400 block sm:inline">N/A</span></div><div>THỜI TIẾT: <span class="font-sans font-extrabold text-emerald-450 block sm:inline">N/A</span></div><div>ĐỘ CAO: <span class="font-sans font-extrabold text-stone-400 block sm:inline">N/A</span></div><div>SỨC GIÓ: <span class="font-sans font-extrabold text-cyan-450 block sm:inline">N/A</span></div></div></div><div class="mb-6 relative z-10"><span class="font-mono text-[10px] md:text-[8px] text-amber-500 uppercase tracking-[0.3em] font-black block mb-1">★ POLAR FLIGHT LOG: PART <!-- -->7<!-- -->, CHAP. <!-- -->1<!-- --> ★</span><h2 class="font-prata text-2xl md:text-3xl text-emerald-300 uppercase font-normal tracking-wide">GÃ KHỔNG LỒ CỦA ĐẠI DƯƠNG</h2><span class="font-serif italic text-sm md:text-xs text-stone-400 block mt-0.5">"<!-- -->KHOẢNH KHẮC ĐÁNG NHỚ NHẤT<!-- -->" — Trích dã sử viễn chinh</span></div><div class="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start relative z-10"><div class="lg:col-span-8 space-y-4"><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all"><span class="float-left text-3xl font-mono border-2 border-dashed border-amber-500/30 text-amber-500 bg-amber-500/5 p-1.5 px-2.5 rounded-lg mr-2 font-bold leading-none select-none">†</span>Nếu có một trải nghiệm khiến nhiều du khách nhớ mãi sau chuyến đi Alaska, đó thường là khoảnh khắc nhìn thấy cá voi xuất hiện giữa đại dương.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Giữa vùng biển lạnh giá của phương Bắc, mặt nước bỗng chuyển động, rồi một thân hình khổng lồ từ từ nổi lên.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Tiếng thở vang vọng trên mặt biển, chiếc đuôi lớn hất lên trước khi lặn sâu xuống là những hình ảnh khiến nhiều người không thể quên.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Alaska từ lâu được xem là một trong những điểm đến hàng đầu thế giới để ngắm cá voi trong môi trường tự nhiên.</p><p class="font-serif text-[16px] md:text-[14.5px] leading-relaxed text-justify text-stone-300 tracking-wide select-all">Mỗi mùa hè, hàng nghìn cá thể cá voi di cư về đây để kiếm ăn, tạo nên một trong những hiện tượng thiên nhiên ấn tượng nhất của vùng đất này.</p><div class="p-4 rounded-xl border-y border-dashed relative my-5 bg-white/[0.015] border-white/5 text-amber-100"><span class="font-mono text-[9px] md:text-[7px] text-stone-450 uppercase tracking-widest block mb-1.5">✍️ BÚT TÍCH NGHIÊN CỨU:</span><p class="font-serif text-[15.5px] md:text-[13.5px] italic leading-relaxed text-left">"<!-- -->Tiếng thở vang vọng trên mặt biển, chiếc đuôi lớn hất lên trước khi lặn sâu xuống là những hình ảnh khiến nhiều người không thể quên.<!-- -->"</p></div></div><div class="lg:col-span-4 space-y-4"><div class="bg-red-950/25 border border-red-500/20 rounded-2xl p-4 text-left space-y-2 relative overflow-hidden"><div class="absolute top-0 right-0 w-12 h-12 bg-red-500/5 rounded-full blur-xl pointer-events-none"></div><div class="flex items-center gap-1.5 text-red-400 font-mono text-[10px] md:text-[8px] font-black uppercase tracking-widest"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-compass w-3.5 h-3.5 text-red-500 animate-spin-slow" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z"></path></svg><span>KHUYẾN CÁO SINH TỒN THỰC ĐỊA</span></div><p class="font-serif text-sm md:text-xs md:text-xxs text-stone-300 leading-relaxed"></p><div class="pt-2 border-t border-white/5 flex justify-between items-center text-[9.5px] md:text-[7.5px] font-mono text-red-400"><span>SỔ TẠY HUẤN LUYỆN</span><span class="cursor-pointer underline">Mở hòm vật tư ↳</span></div></div><div class="bg-amber-50 border border-amber-900/10 rounded-xl p-4 rotate-1 shadow-md text-stone-900 space-y-2"><span class="font-mono text-[9px] md:text-[7px] text-amber-900/90 uppercase tracking-widest block font-bold border-b border-amber-900/10 pb-1">📋 MEMOIR NOTE:</span><p class="font-sans text-[13px] md:text-[11px] font-medium leading-relaxed text-justify italic text-stone-850">"<!-- -->Tiếng thở vang vọng trên mặt biển, chiếc đuôi lớn hất lên trước khi lặn sâu xuống là những hình ảnh khiến nhiều người không thể quên.<!-- -->"</p><span class="font-mono text-[9.5px] md:text-[7.5px] text-stone-500 block text-right">— Signed, Curator Max Vu</span></div></div></div><div class="flex justify-between items-center border-t border-white/5 pt-4.5 mt-6 relative z-10 select-none"><span class="font-mono text-[10px] md:text-[8px] text-stone-505 tracking-wider hidden sm:block">EST. JUNE 12, 2026 • ARNATIC LOGS BY FIT TOUR</span></div><div class="flex gap-4 justify-center py-2 text-stone-700/10 select-none pointer-events-none mt-4"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-footprints w-4.5 h-4.5 rotate-12 opacity-30" aria-hidden="true"><path d="M4 16v-2.38C4 11.5 2.97 10.5 3 8c.03-2.72 1.49-6 4.5-6C9.37 2 10 3.8 10 5.5c0 3.11-2 5.66-2 8.68V16a2 2 0 1 1-4 0Z"></path><path d="M20 20v-2.38c0-2.12 1.03-3.12 1-5.62-.03-2.72-1.49-6-4.5-6C14.63 6 14 7.8 14 9.5c0 3.11 2 5.66 2 8.68V20a2 2 0 1 0 4 0Z"></path><path d="M16 17h4"></path><path d="M4 13h4"></path></svg><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-footprints w-4.5 h-4.5 -rotate-12 opacity-25 mt-1" aria-hidden="true"><path d="M4 16v-2.38C4 11.5 2.97 10.5 3 8c.03-2.72 1.49-6 4.5-6C9.37 2 10 3.8 10 5.5c0 3.11-2 5.66-2 8.68V16a2 2 0 1 1-4 0Z"></path><path d="M20 20v-2.38c0-2.12 1.03-3.12 1-5.62-.03-2.72-1.49-6-4.5-6C14.63 6 14 7.8 14 9.5c0 3.11 2 5.66 2 8.68V20a2 2 0 1